import{c as o,Q as r,j as t,m as s}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"宋词三百首","description":"","frontmatter":{"id":"songci","title":"宋词三百首","author":"朱孝臧","dynasty":"清代","cover":"/covers/songci.jpg","sort":2,"literaryValue":"《宋词三百首》是清代朱孝臧编选的宋词选集，收录了宋代众多词人的代表作。宋词是继唐诗之后的又一文学高峰，分为豪放派和婉约派，展现了宋代文人的情感世界和艺术追求。"},"headers":[],"relativePath":"books/shici/songci.md","filePath":"books/shici/songci.md"}'),e={name:"books/shici/songci.md"};function n(i,a,h,p,l,c){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="宋词三百首" tabindex="-1">宋词三百首 <a class="header-anchor" href="#宋词三百首" aria-label="Permalink to &quot;宋词三百首&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>《宋词三百首》是清代朱孝臧编选的宋词选集。朱孝臧（1857年—1931年），原名祖谋，字藿生，一字古微，号沤尹，又号彊村，浙江归安（今湖州）人。光绪九年（1883年）进士，官至礼部右侍郎。工诗词，为清末四大词家之一。</p><p>宋词是继唐诗之后的又一文学高峰，分为豪放派和婉约派，展现了宋代文人的情感世界和艺术追求。宋词在形式上突破了唐诗的格律限制，采用长短句的形式，更加灵活自由，能够更好地表达复杂的情感。</p><h2 id="编选特点" tabindex="-1">编选特点 <a class="header-anchor" href="#编选特点" aria-label="Permalink to &quot;编选特点&quot;">​</a></h2><p>《宋词三百首》的编选特点：</p><ol><li><strong>选目精当</strong>：所选词作都是宋词中的精华，代表了宋词的最高成就</li><li><strong>风格多样</strong>：既有豪放派的苏轼、辛弃疾，又有婉约派的李清照、柳永</li><li><strong>题材广泛</strong>：涵盖咏史怀古、山水田园、爱情闺怨、送别赠答等各种题材</li><li><strong>便于学习</strong>：篇幅适中，注释简明，非常适合初学者入门</li></ol><h2 id="豪放派" tabindex="-1">豪放派 <a class="header-anchor" href="#豪放派" aria-label="Permalink to &quot;豪放派&quot;">​</a></h2><h3 id="念奴娇·赤壁怀古" tabindex="-1">念奴娇·赤壁怀古 <a class="header-anchor" href="#念奴娇·赤壁怀古" aria-label="Permalink to &quot;念奴娇·赤壁怀古&quot;">​</a></h3><p><strong><a href="/books/shici/songci/1.html">查看详情</a></strong></p><p><strong>苏轼</strong></p><p>大江东去，浪淘尽，千古风流人物。 故垒西边，人道是，三国周郎赤壁。 乱石穿空，惊涛拍岸，卷起千堆雪。 江山如画，一时多少豪杰。</p><p>遥想公瑾当年，小乔初嫁了，雄姿英发。 羽扇纶巾，谈笑间，樯橹灰飞烟灭。 故国神游，多情应笑我，早生华发。 人生如梦，一尊还酹江月。</p><h3 id="水调歌头" tabindex="-1">水调歌头 <a class="header-anchor" href="#水调歌头" aria-label="Permalink to &quot;水调歌头&quot;">​</a></h3><p><strong><a href="/books/shici/songci/2.html">查看详情</a></strong></p><p><strong>苏轼</strong></p><p>明月几时有？把酒问青天。 不知天上宫阙，今夕是何年。 我欲乘风归去，又恐琼楼玉宇，高处不胜寒。 起舞弄清影，何似在人间。</p><p>转朱阁，低绮户，照无眠。 不应有恨，何事长向别时圆？ 人有悲欢离合，月有阴晴圆缺，此事古难全。 但愿人长久，千里共婵娟。</p><h3 id="永遇乐·京口北固亭怀古" tabindex="-1">永遇乐·京口北固亭怀古 <a class="header-anchor" href="#永遇乐·京口北固亭怀古" aria-label="Permalink to &quot;永遇乐·京口北固亭怀古&quot;">​</a></h3><p><strong><a href="/books/shici/songci/3.html">查看详情</a></strong></p><p><strong>辛弃疾</strong></p><p>千古江山，英雄无觅孙仲谋处。 舞榭歌台，风流总被雨打风吹去。 斜阳草树，寻常巷陌，人道寄奴曾住。 想当年，金戈铁马，气吞万里如虎。</p><p>元嘉草草，封狼居胥，赢得仓皇北顾。 四十三年，望中犹记，烽火扬州路。 可堪回首，佛狸祠下，一片神鸦社鼓。 凭谁问：廉颇老矣，尚能饭否？</p><h3 id="破阵子·为陈同甫赋壮词以寄之" tabindex="-1">破阵子·为陈同甫赋壮词以寄之 <a class="header-anchor" href="#破阵子·为陈同甫赋壮词以寄之" aria-label="Permalink to &quot;破阵子·为陈同甫赋壮词以寄之&quot;">​</a></h3><p><strong><a href="/books/shici/songci/4.html">查看详情</a></strong></p><p><strong>辛弃疾</strong></p><p>醉里挑灯看剑，梦回吹角连营。 八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。</p><p>马作的卢飞快，弓如霹雳弦惊。 了却君王天下事，赢得生前身後名。可怜白发生！</p><h2 id="婉约派" tabindex="-1">婉约派 <a class="header-anchor" href="#婉约派" aria-label="Permalink to &quot;婉约派&quot;">​</a></h2><h3 id="声声慢" tabindex="-1">声声慢 <a class="header-anchor" href="#声声慢" aria-label="Permalink to &quot;声声慢&quot;">​</a></h3><p><strong><a href="/books/shici/songci/1.html">查看详情</a></strong></p><p><strong>李清照</strong></p><p>寻寻觅觅，冷冷清清，凄凄惨惨戚戚。 乍暖还寒时候，最难将息。 三杯两盏淡酒，怎敌他、晚来风急？ 雁过也，正伤心，却是旧时相识。</p><p>满地黄花堆积。憔悴损，如今有谁堪摘？ 守着窗儿，独自怎生得黑？ 梧桐更兼细雨，到黄昏、点点滴滴。 这次第，怎一个愁字了得！</p><h3 id="如梦令" tabindex="-1">如梦令 <a class="header-anchor" href="#如梦令" aria-label="Permalink to &quot;如梦令&quot;">​</a></h3><p><strong><a href="/books/shici/songci/2.html">查看详情</a></strong></p><p><strong>李清照</strong></p><p>昨夜雨疏风骤，浓睡不消残酒。 试问卷帘人，却道海棠依旧。 知否，知否？应是绿肥红瘦。</p><h3 id="醉花阴" tabindex="-1">醉花阴 <a class="header-anchor" href="#醉花阴" aria-label="Permalink to &quot;醉花阴&quot;">​</a></h3><p><strong><a href="/books/shici/songci/3.html">查看详情</a></strong></p><p><strong>李清照</strong></p><p>薄雾浓云愁永昼，瑞脑消金兽。 佳节又重阳，玉枕纱厨，半夜凉初透。</p><p>东篱把酒黄昏後，有暗香盈袖。 莫道不销魂，帘卷西风，人比黄花瘦。</p><h3 id="雨霖铃" tabindex="-1">雨霖铃 <a class="header-anchor" href="#雨霖铃" aria-label="Permalink to &quot;雨霖铃&quot;">​</a></h3><p><strong><a href="/books/shici/songci/4.html">查看详情</a></strong></p><p><strong>柳永</strong></p><p>寒蝉凄切，对长亭晚，骤雨初歇。 都门帐饮无绪，留恋处，兰舟催发。 执手相看泪眼，竟无语凝噎。 念去去，千里烟波，暮霭沉沉楚天阔。</p><p>多情自古伤离别，更那堪，冷落清秋节！ 今宵酒醒何处？杨柳岸，晓风残月。 此去经年，应是良辰好景虚设。 便纵有千种风情，更与何人说？</p><h3 id="蝶恋花" tabindex="-1">蝶恋花 <a class="header-anchor" href="#蝶恋花" aria-label="Permalink to &quot;蝶恋花&quot;">​</a></h3><p><strong><a href="/books/shici/songci/5.html">查看详情</a></strong></p><p><strong>柳永</strong></p><p>伫倚危楼风细细，望极春愁，黯黯生天际。 草色烟光残照里，无言谁会凭阑意。</p><p>拟把疏狂图一醉，对酒当歌，强乐还无味。 衣带渐宽终不悔，为伊消得人憔悴。</p><h2 id="其他名家" tabindex="-1">其他名家 <a class="header-anchor" href="#其他名家" aria-label="Permalink to &quot;其他名家&quot;">​</a></h2><h3 id="鹊桥仙" tabindex="-1">鹊桥仙 <a class="header-anchor" href="#鹊桥仙" aria-label="Permalink to &quot;鹊桥仙&quot;">​</a></h3><p><strong><a href="/books/shici/songci/6.html">查看详情</a></strong></p><p><strong>秦观</strong></p><p>纤云弄巧，飞星传恨，银汉迢迢暗度。 金风玉露一相逢，便胜却人间无数。</p><p>柔情似水，佳期如梦，忍顾鹊桥归路。 两情若是久长时，又岂在朝朝暮暮。</p><h3 id="青玉案·元夕" tabindex="-1">青玉案·元夕 <a class="header-anchor" href="#青玉案·元夕" aria-label="Permalink to &quot;青玉案·元夕&quot;">​</a></h3><p><strong><a href="/books/shici/songci/1.html">查看详情</a></strong></p><p><strong>辛弃疾</strong></p><p>东风夜放花千树，更吹落，星如雨。 宝马雕车香满路。 凤箫声动，玉壶光转，一夜鱼龙舞。</p><p>蛾儿雪柳黄金缕，笑语盈盈暗香去。 众里寻他千百度，蓦然回首， 那人却在，灯火阑珊处。</p><h3 id="满江红·写怀" tabindex="-1">满江红·写怀 <a class="header-anchor" href="#满江红·写怀" aria-label="Permalink to &quot;满江红·写怀&quot;">​</a></h3><p><strong><a href="/books/shici/songci/2.html">查看详情</a></strong></p><p><strong>岳飞</strong></p><p>怒发冲冠，凭栏处、潇潇雨歇。 抬望眼，仰天长啸，壮怀激烈。 三十功名尘与土，八千里路云和月。 莫等闲，白了少年头，空悲切！</p><p>靖康耻，犹未雪。臣子恨，何时灭！ 驾长车，踏破贺兰山缺。 壮志饥餐胡虏肉，笑谈渴饮匈奴血。 待从头、收拾旧山河，朝天阙。</p><h3 id="卜算子·咏梅" tabindex="-1">卜算子·咏梅 <a class="header-anchor" href="#卜算子·咏梅" aria-label="Permalink to &quot;卜算子·咏梅&quot;">​</a></h3><p><strong><a href="/books/shici/songci/3.html">查看详情</a></strong></p><p><strong>陆游</strong></p><p>驿外断桥边，寂寞开无主。 已是黄昏独自愁，更著风和雨。</p><p>无意苦争春，一任群芳妒。 零落成泥碾作尘，只有香如故。</p><h2 id="影响与评价" tabindex="-1">影响与评价 <a class="header-anchor" href="#影响与评价" aria-label="Permalink to &quot;影响与评价&quot;">​</a></h2><p>宋词是中国文学史上的一座高峰，与唐诗并称&quot;唐诗宋词&quot;，代表了中国古典诗歌的最高成就。宋词在形式上突破了唐诗的格律限制，采用长短句的形式，更加灵活自由，能够更好地表达复杂的情感。在内容上，宋词题材广泛，风格多样，既有豪放派的慷慨激昂，又有婉约派的缠绵悱恻，展现了宋代文人的情感世界和艺术追求。</p><p>《宋词三百首》作为宋词选本的代表，自问世以来一直受到读者的喜爱，成为学习宋词的必读之书。该书不仅为读者提供了一个了解宋词的窗口，也成为中国古典文学教育的重要教材。</p>',77)])])}const b=o(e,[["render",n]]);export{d as __pageData,b as default};
